package com.madhukar.upisplitter.config;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.time.Instant; import java.util.concurrent.ConcurrentHashMap; import java.util.concurrent.atomic.AtomicInteger;
@Component public class RateLimitConfig extends OncePerRequestFilter {private record Bucket(AtomicInteger count,long window){} private final ConcurrentHashMap<String,Bucket> map=new ConcurrentHashMap<>();protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{if(r.getRequestURI().startsWith("/api/auth/")){String ip=r.getRemoteAddr();long now=Instant.now().getEpochSecond();Bucket b=map.compute(ip,(k,v)->v==null||now-v.window>=60?new Bucket(new AtomicInteger(0),now):v);if(b.count.incrementAndGet()>30){s.setStatus(429);s.setContentType("application/json");s.getWriter().write("{\"success\":false,\"message\":\"Too many requests. Try again later.\"}");return;}}c.doFilter(r,s);}}
